# =============================================================================
# Moderna P301: weekly county COVID-19 positivity map
# analyse_background_covid_map_sites_only.R | v1.1.0 | 22 October 2026
# Standalone: put in the project root, select all and run in RStudio.
# Run analyse_background_covid.R first. No other script is sourced or executed.
# Reads analysis/background_covid/county_weekly.csv (or site_weekly.csv).
# Also accepts the reviewed heatmap export site_background_used.csv explicitly.
# HTML is fully offline. Census 2020 boundaries and Leaflet are embedded below.
# GIF uses the SAME county-week values and fixed colour classes as the HTML.
# Scope: contiguous United States + DC, covering all 99 current P301 sites.
# 0% reported positivity is NOT evidence of no infection; missing is never zero.
# No state fallback, interpolation, smoothing or pooling of county percentages.
# Packages: jsonlite; GIF: gifski, magick, or an installed ImageMagick executable.
# Windows: never invokes the unrelated Windows convert.exe utility.
# To load functions only: options(phmpt.autorun=FALSE) before source().
# =============================================================================
PHMPT_MAP_ROOT <- normalizePath(getOption("phmpt.root", getwd()), winslash="/", mustWork=TRUE)
PHMPT_MAP_INPUT <- getOption("phmpt.map.input", "") # empty = automatic standard input
PHMPT_MAP_SITES <- file.path(PHMPT_MAP_ROOT, "clinical_trial_sites.csv")
PHMPT_MAP_OUTPUT <- file.path(PHMPT_MAP_ROOT, "analysis", "county_pandemic_map_sites_only")
PHMPT_MAP_START <- ""       # e.g. "2020-07-27"; empty = earliest supplied week
PHMPT_MAP_END <- ""         # e.g. "2021-03-28"; only complete weeks up to this date
PHMPT_MAP_SHOW_SITES <- TRUE
PHMPT_MAP_WRITE_GIF <- TRUE
PHMPT_MAP_GIF_WIDTH <- 1500L
PHMPT_MAP_GIF_HEIGHT <- 1000L
PHMPT_MAP_SECONDS_PER_WEEK <- 0.8
PHMPT_MAP_GIF_ENGINE <- "auto" # auto, gifski, magick, or imagemagick
PHMPT_MAP_KEEP_FRAMES <- TRUE  # individual PNGs are also useful for print
PHMPT_MAP_INSTALL_MISSING <- TRUE
PHMPT_MAP_OPEN_HTML <- interactive()

pm_read <- function(path) utils::read.csv(path, colClasses="character", check.names=FALSE,
  stringsAsFactors=FALSE, fileEncoding="UTF-8-BOM", na.strings=c("", "NA", "N/A"))
pm_csv <- function(x,path) utils::write.csv(x,path,row.names=FALSE,na="",fileEncoding="UTF-8")
pm_path <- function(root,x) if(grepl("^([A-Za-z]:[/\\\\]|/|~)",x)) path.expand(x) else file.path(root,x)
pm_need <- function(x,nms,what) {bad<-setdiff(nms,names(x));if(length(bad))stop(what,": missing ",paste(bad,collapse=", "),call.=FALSE)}
pm_num <- function(x) suppressWarnings(as.numeric(gsub(",",".",trimws(as.character(x)),fixed=TRUE)))
pm_fips <- function(x) {v<-pm_num(x);ifelse(is.finite(v)&v==floor(v)&v>=1000&v<=99999,sprintf("%05d",as.integer(v)),NA_character_)}
pm_require <- function(pkg,install) {
  if(!requireNamespace(pkg,quietly=TRUE)&&install) try(utils::install.packages(pkg,repos="https://cloud.r-project.org"),silent=TRUE)
  if(!requireNamespace(pkg,quietly=TRUE))stop("Package '",pkg,"' is required. Run install.packages('",pkg,"') and rerun.",call.=FALSE)
}
pm_date <- function(x,what) {
  s<-trimws(as.character(x)); if(any(is.na(s)|!grepl("^[0-9]{4}-[0-9]{2}-[0-9]{2}$",s)))stop(what,": use complete ISO dates YYYY-MM-DD.")
  d<-as.Date(s,format="%Y-%m-%d");if(anyNA(d))stop(what,": invalid date.");d
}
pm_monday <- function(d) as.Date(d)-((as.integer(as.Date(d))+3L)%%7L)
pm_json <- function(x) gsub("</","<\\/",as.character(jsonlite::toJSON(x,auto_unbox=TRUE,na="null",null="null",digits=8,force=TRUE)),fixed=TRUE)
pm_colours <- function() c("#bdbdbd","#fee5d9","#fcae91","#fb6a4a","#de2d26","#a50f15","#67000d")
pm_labels <- function() c("0% reported",">0 to <5%","5 to <10%","10 to <15%","15 to <20%","20 to <30%","30 to 100%")
pm_class <- function(x) {
  ans<-rep(NA_integer_,length(x));good<-is.finite(x)&x>=0&x<=100
  ans[good]<-findInterval(x[good],c(0,5,10,15,20,30))+1L
  ans[good&x==0]<-1L;ans
}
pm_input <- function(root,input) {
  if(nzchar(input)){p<-pm_path(root,input);if(!file.exists(p))stop("Input not found: ",p);return(normalizePath(p,winslash="/"))}
  for(n in c("county_weekly.csv","site_weekly.csv")){
    p<-file.path(root,"analysis","background_covid",n);if(file.exists(p))return(normalizePath(p,winslash="/"))
  }
  candidates<-list.files(file.path(root,"analysis"),pattern="^county_weekly[.]csv$",recursive=TRUE,full.names=TRUE)
  if(length(candidates)==1L)return(normalizePath(candidates,winslash="/"))
  if(length(candidates)>1L)stop("Several background runs found. Set PHMPT_MAP_INPUT to one county_weekly.csv:\n",paste(candidates,collapse="\n"))
  stop("No background CSV found. Run analyse_background_covid.R first, or set PHMPT_MAP_INPUT to county_weekly.csv / site_weekly.csv.",call.=FALSE)
}
pm_normalise <- function(d,output) {
  get<-function(n,default="")if(n%in%names(d))d[[n]] else rep(default,nrow(d))
  if(all(c("geography_id","week_start","positivity_pct")%in%names(d))){
    if("geography_level"%in%names(d)&&any(is.na(d$geography_level)|tolower(d$geography_level)!="county"))stop("Input contains non-county geography. Use county_weekly.csv.")
    z<-data.frame(fips=pm_fips(d$geography_id),week_start=d$week_start,week_end=get("week_end",NA_character_),
      positivity=pm_num(d$positivity_pct),cases=pm_num(get("new_reported_cases",NA)),
      status=get("positivity_status"),site_ids=get("site_ids"),source=get("positivity_source"),stringsAsFactors=FALSE)
    kind<-"county_weekly.csv"
  }else if(all(c("county_fips","week_start","county_positivity_pct")%in%names(d))){
    # Explicitly ignores best_available_positivity_pct and all state fallback values.
    z<-data.frame(fips=pm_fips(d$county_fips),week_start=d$week_start,week_end=get("week_end",NA_character_),
      positivity=pm_num(d$county_positivity_pct),cases=pm_num(get("county_cases",NA)),
      status="county-only field from site_weekly",site_ids=get("SITEID"),
      source="County positivity from analyse_background_covid.R",stringsAsFactors=FALSE)
    kind<-"site_weekly.csv (county fields only)"
  }else if(all(c("SITEID","region_key","week","cases","positivity")%in%names(d))){
    if(any(is.na(d$region_key)|!grepl("^county_[0-9]{5}$",d$region_key)))stop("Heatmap export contains a state or unrecognized region. Use the original county_weekly.csv; state values cannot colour counties.")
    z<-data.frame(fips=sub("^county_","",d$region_key),week_start=d$week,week_end=NA_character_,
      positivity=pm_num(d$positivity),cases=pm_num(d$cases),status="county value preserved in heatmap export",
      site_ids=d$SITEID,source="County background value retained in site_background_used.csv",stringsAsFactors=FALSE)
    kind<-"site_background_used.csv (county regions only)"
  }else stop("Unrecognized CSV schema. Expected county_weekly.csv or site_weekly.csv from analyse_background_covid.R.")
  if(!nrow(z))stop("Empty background input.")
  if(anyNA(z$fips))stop("Missing/invalid county FIPS. Correct the geography input; rows were not silently discarded.")
  z$week_start<-pm_date(z$week_start,"week_start")
  if(any(z$week_start!=pm_monday(z$week_start)))stop("Weeks must start on Monday, as in analyse_background_covid.R.")
  wend<-z$week_start+6
  if(any(!is.na(z$week_end)&nzchar(z$week_end))){ix<-!is.na(z$week_end)&nzchar(z$week_end);if(any(pm_date(z$week_end[ix],"week_end")!=wend[ix]))stop("week_end must be week_start + 6 days.")}
  z$week_end<-wend
  invalid<-is.finite(z$positivity)&(z$positivity<0|z$positivity>100)|is.infinite(z$positivity)
  if(any(invalid)){pm_csv(z[invalid,],file.path(output,"invalid_positivity.csv"));stop("Positivity outside 0..100. See invalid_positivity.csv; percentages must not be fractions.")}
  # Reject conflicting duplicate county-weeks. Shared sites are not independent observations.
  key<-paste(z$fips,z$week_start)
  groups<-split(seq_len(nrow(z)),key)
  conflict<-vapply(groups,function(i)length(unique(z$positivity[i]))>1L||length(unique(z$cases[i]))>1L,logical(1))
  if(any(conflict)){pm_csv(z[key%in%names(groups)[conflict],],file.path(output,"conflicting_county_weeks.csv"));stop("Conflicting county-week observations; see conflicting_county_weeks.csv. No averaging was performed.")}
  out<-z[!duplicated(key),];out<-out[order(out$week_start,out$fips),]
  for(i in seq_len(nrow(out))){ix<-groups[[paste(out$fips[i],out$week_start[i])]];out$site_ids[i]<-paste(sort(unique(trimws(unlist(strsplit(paste(z$site_ids[ix],collapse=";"),";"))))),collapse="; ")}
  list(data=out,input_kind=kind,input_rows=nrow(z),duplicate_rows_removed=nrow(z)-nrow(out))
}
pm_load_sites <- function(path,data,show) {
  empty<-data.frame(SITEID=character(),site_name=character(),latitude=numeric(),longitude=numeric(),county_fips=character())
  if(!show)return(empty)
  if(!file.exists(path)){warning("clinical_trial_sites.csv not found; maps will omit site markers.",call.=FALSE);return(empty)}
  s<-pm_read(path);pm_need(s,c("SITEID","site_name","latitude","longitude"),"clinical_trial_sites.csv")
  if(anyNA(s$SITEID)||anyDuplicated(s$SITEID))stop("Missing/duplicate site IDs in clinical_trial_sites.csv.")
  s$latitude<-pm_num(s$latitude);s$longitude<-pm_num(s$longitude)
  if(any(!is.finite(s$latitude)|!is.finite(s$longitude)|s$latitude<24|s$latitude>50|s$longitude< -126|s$longitude> -66))stop("Site coordinates fall outside this contiguous-US map. Check the asset; sites were not silently dropped.")
  links<-unique(data[c("fips","site_ids")]);s$county_fips<-NA_character_
  for(i in seq_len(nrow(s))){h<-links$fips[vapply(strsplit(ifelse(is.na(links$site_ids),"",links$site_ids),";"),function(v)s$SITEID[i]%in%trimws(v),logical(1))];h<-unique(h);if(length(h)>1L)stop("Site has multiple county assignments: ",s$SITEID[i]);if(length(h))s$county_fips[i]<-h}
  s[c("SITEID","site_name","latitude","longitude","county_fips")]
}
pm_ring <- function(r) {m<-matrix(as.numeric(unlist(r)),ncol=2,byrow=TRUE);cbind(m[,1],log(tan(pi/4+m[,2]*pi/360))*180/pi)}
pm_shapes <- function(geo) lapply(geo$features,function(f){
  polys<-if(f$geometry$type=="Polygon")list(f$geometry$coordinates) else if(f$geometry$type=="MultiPolygon")f$geometry$coordinates else stop("Unexpected geometry type")
  rings<-unlist(lapply(polys,function(p)lapply(p,pm_ring)),recursive=FALSE)
  list(properties=f$properties,rings=rings)
})
pm_draw <- function(shape,fill,border,lwd=.5,lty=1) {
  x<-unlist(lapply(shape$rings,function(r)c(r[,1],NA_real_)));y<-unlist(lapply(shape$rings,function(r)c(r[,2],NA_real_)))
  # Cairo rejects a trailing empty subpath; keep separators only between rings.
  x<-head(x,-1L);y<-head(y,-1L)
  graphics::polypath(x,y,col=fill,border=border,rule="evenodd",lwd=lwd,lty=lty)
}
pm_gif_engine <- function(engine,install) {
  if(!engine%in%c("auto","gifski","magick","imagemagick"))stop("Unknown GIF engine: ",engine)
  if(engine%in%c("auto","gifski")&&requireNamespace("gifski",quietly=TRUE))return(list(type="gifski"))
  if(engine%in%c("auto","magick")&&requireNamespace("magick",quietly=TRUE))return(list(type="magick"))
  if(engine%in%c("auto","imagemagick")){
    exes<-c(Sys.which("magick"),if(.Platform$OS.type!="windows")Sys.which("convert"))
    for(exe in exes[nzchar(exes)]){v<-tryCatch(system2(exe,"-version",stdout=TRUE,stderr=TRUE),error=function(e)character());if(any(grepl("ImageMagick",v,fixed=TRUE)))return(list(type="imagemagick",exe=unname(exe)))}
  }
  if(install&&engine%in%c("auto","gifski")){pm_require("gifski",TRUE);return(list(type="gifski"))}
  if(install&&engine=="magick"){pm_require("magick",TRUE);return(list(type="magick"))}
  stop("No GIF encoder. Install gifski (install.packages('gifski')) or magick, then rerun. HTML remains available.")
}
pm_frame <- function(path,index,weeks,grid,county_shapes,state_shapes,site_points,width,height){
  # Render to a private temporary file and publish only after closing the device.
  tmp<-tempfile("county_frame_",fileext=".png")
  grDevices::png(tmp,width=width,height=height,res=125,pointsize=13,type=if(capabilities("cairo"))"cairo" else getOption("bitmapType","Xlib"))
  device<-grDevices::dev.cur();closed<-FALSE
  on.exit({if(!closed)try(grDevices::dev.off(device),silent=TRUE);unlink(tmp)},add=TRUE)
  graphics::par(mar=c(.2,.2,.2,.2),xaxs="i",yaxs="i",family="sans")
  graphics::plot.new();graphics::plot.window(xlim=c(0,1),ylim=c(0,1))
  graphics::text(.04,.966,"Weekly county COVID-19 test positivity",adj=c(0,1),font=2,cex=1.55,col="#153d50")
  graphics::text(.04,.926,paste(format(weeks[index],"%d %B %Y"),"-",format(weeks[index]+6,"%d %B %Y")),adj=c(0,1),font=2,cex=1.18)
  d<-grid[grid$week_start==weeks[index],];coverage<-sum(is.finite(d$positivity))
  graphics::text(.96,.929,paste0("Week ",index," / ",length(weeks),"  |  ",coverage," / ",nrow(d)," counties reported"),adj=c(1,1),cex=.85,col="#536978")
  graphics::par(fig=c(.025,.975,.21,.885),new=TRUE,mar=c(0,0,0,0))
  graphics::plot.new();yl<-log(tan(pi/4+c(24,50)*pi/360))*180/pi
  graphics::plot.window(xlim=c(-126,-66),ylim=yl,asp=1,xaxs="i",yaxs="i")
  graphics::rect(-180,-90,180,180,col="#e8f0f4",border=NA)
  for(s in county_shapes)pm_draw(s,"#fffefa","#d9dedf",.22)
  fips<-vapply(county_shapes,function(s)s$properties$fips,"")
  for(j in seq_len(nrow(d))){s<-county_shapes[[match(d$fips[j],fips)]];k<-d$colour_class[j];pm_draw(s,if(is.na(k))"#ffffff" else pm_colours()[k],"#475e6e",.55,if(is.na(k))2 else 1)}
  for(s in state_shapes)pm_draw(s,NA,"#8496a2",.65)
  if(nrow(site_points))graphics::points(site_points$longitude,log(tan(pi/4+site_points$latitude*pi/360))*180/pi,pch=21,cex=.48,bg="#ffffff",col="#113f55",lwd=.6)
  graphics::par(fig=c(0,1,0,1),new=TRUE,mar=c(0,0,0,0));graphics::plot.new();graphics::plot.window(xlim=c(0,1),ylim=c(0,1))
  colours<-c(pm_colours(),"#ffffff");labels<-c(pm_labels(),"No county value")
  for(k in seq_along(colours)){x<-.035+(k-1)*.12;graphics::rect(x,.153,x+.022,.176,col=colours[k],border="#687b88",lty=if(k==8)2 else 1);graphics::text(x+.029,.165,labels[k],adj=0,cex=.62)}
  graphics::text(.035,.112,"Fixed scale. Pale counties: outside series; white dashed counties: no weekly value.",adj=0,cex=.69,col="#455d6b")
  graphics::text(.035,.080,"Grey = 0% reported positivity, not absence of infection. Site county may differ from residence.",adj=0,cex=.69,col="#455d6b")
  graphics::text(.035,.048,"CDC county NAAT archive; US Census 2020 boundaries (1:20m). Dots: trial sites.",adj=0,cex=.67,col="#455d6b")
  # Animation position: first frame at the left, last frame at the right.
  # Date labels describe the full observation window, including the last Sunday.
  graphics::rect(.735,.025,.982,.123,col="#f4f7f9",border="#dce5eb",lwd=.7)
  tx0<-.750;tx1<-.968;ty<-.075
  progress<-if(length(weeks)>1L)(index-1)/(length(weeks)-1)else 1
  cursor<-tx0+(tx1-tx0)*progress
  graphics::text(tx0,.105,"Animation progress",adj=0,font=2,cex=.67,col="#174d67")
  graphics::text(tx1,.105,paste0("Week ",index," / ",length(weeks)),adj=1,cex=.65,col="#455d6b")
  graphics::segments(tx0,ty,tx1,ty,col="#d4dfe6",lwd=4,lend="round")
  if(progress>0)graphics::segments(tx0,ty,cursor,ty,col="#174d67",lwd=4,lend="round")
  graphics::points(cursor,ty,pch=21,cex=.85,col="white",bg="#174d67",lwd=1.1)
  graphics::text(tx0,.044,format(min(weeks),"%d %b %Y"),adj=0,cex=.64,col="#455d6b")
  graphics::text(tx1,.044,format(max(weeks)+6,"%d %b %Y"),adj=1,cex=.64,col="#455d6b")
  grDevices::dev.off(device);closed<-TRUE
  if(!file.exists(tmp)||is.na(file.info(tmp)$size)||file.info(tmp)$size<100)stop("PNG device failed for ",weeks[index])
  if(!file.copy(tmp,path,overwrite=TRUE))stop("Could not save PNG frame: ",path)
}
pm_write_gif <- function(frames,dest,encoder,width,height,delay){
  if(encoder$type=="gifski")gifski::gifski(frames,gif_file=dest,width=width,height=height,delay=delay,loop=TRUE)
  else if(encoder$type=="magick"){
    im<-magick::image_read(frames);im<-magick::image_animate(im,delay=max(1L,round(100*delay)),loop=0,dispose="background")
    magick::image_write(im,path=dest,format="gif")
  }else{
    args<-c("-delay",as.character(max(1L,round(100*delay))),shQuote(normalizePath(frames,winslash="/")),"-loop","0",shQuote(dest))
    code<-system2(encoder$exe,args);if(!identical(code,0L))stop("ImageMagick GIF encoding failed (exit ",code,"). PNG frames and HTML remain available.")
  }
  if(!file.exists(dest)||file.info(dest)$size<100)stop("GIF file was not produced.")
}
analyse_background_covid_map <- function(root=PHMPT_MAP_ROOT,input=PHMPT_MAP_INPUT,
  sites_file=PHMPT_MAP_SITES,output=PHMPT_MAP_OUTPUT,start=PHMPT_MAP_START,end=PHMPT_MAP_END,
  show_sites=PHMPT_MAP_SHOW_SITES,write_gif=PHMPT_MAP_WRITE_GIF,width=PHMPT_MAP_GIF_WIDTH,
  height=PHMPT_MAP_GIF_HEIGHT,delay=PHMPT_MAP_SECONDS_PER_WEEK,gif_engine=PHMPT_MAP_GIF_ENGINE,
  keep_frames=PHMPT_MAP_KEEP_FRAMES,install_missing=PHMPT_MAP_INSTALL_MISSING,open_html=PHMPT_MAP_OPEN_HTML){
  root<-normalizePath(root,winslash="/",mustWork=TRUE);output<-pm_path(root,output);dir.create(output,recursive=TRUE,showWarnings=FALSE)
  output<-normalizePath(output,winslash="/",mustWork=TRUE)
  complete<-FALSE;on.exit(if(!complete)writeLines("INCOMPLETE: see the R error. Any existing outputs may be from a partial or earlier run.",file.path(output,"RUN_STATUS.txt")),add=TRUE)
  if(length(width)!=1L||length(height)!=1L||!is.finite(width)||!is.finite(height)||width<1000||height<650)stop("GIF dimensions must be at least 1000 x 650.")
  if(length(delay)!=1L||!is.finite(delay)||delay<.1)stop("Seconds per week must be >= 0.1.")
  pm_require("jsonlite",install_missing)
  source<-pm_input(root,input);message("Reading ",source);norm<-pm_normalise(pm_read(source),output);d<-norm$data
  if(nzchar(start))d<-d[d$week_start>=pm_date(start,"PHMPT_MAP_START"),]
  if(nzchar(end))d<-d[d$week_end<=pm_date(end,"PHMPT_MAP_END"),]
  if(!nrow(d))stop("No complete weeks within the requested dates.")
  counties<-jsonlite::fromJSON(pm_asset("counties"),simplifyVector=FALSE)
  states<-jsonlite::fromJSON(pm_asset("states"),simplifyVector=FALSE)
  cf<-vapply(counties$features,function(f)f$properties$fips,"")
  bad<-setdiff(d$fips,cf);if(length(bad))stop("County FIPS absent from the embedded contiguous-US 2020 boundaries: ",paste(bad,collapse=", "),". Check the geography vintage; no substitution was made.")
  weeks<-seq(min(d$week_start),max(d$week_start),by="7 days");ids<-sort(unique(d$fips))
  grid<-expand.grid(fips=ids,week_start=weeks,stringsAsFactors=FALSE);grid$week_start<-as.Date(grid$week_start,origin="1970-01-01")
  hit<-match(paste(grid$fips,grid$week_start),paste(d$fips,d$week_start));grid$week_end<-grid$week_start+6
  for(n in c("positivity","cases","status","site_ids","source"))grid[[n]]<-d[[n]][hit]
  grid$status[is.na(hit)]<-"No source row for this county-week"
  grid$status[is.na(grid$positivity)&(is.na(grid$status)|grid$status=="")]<-"Missing or suppressed"
  grid$colour_class<-pm_class(grid$positivity)
  props<-lapply(counties$features[match(ids,cf)],function(f)f$properties)
  areas<-data.frame(fips=ids,name=vapply(props,function(p)paste(p$name,p$state,sep=", "),""),state=vapply(props,function(p)p$state,""),stringsAsFactors=FALSE)
  grid$county_name<-areas$name[match(grid$fips,areas$fips)]
  areas$site_ids<-vapply(ids,function(id){x<-d$site_ids[d$fips==id];paste(sort(unique(trimws(unlist(strsplit(paste(x[!is.na(x)],collapse=";"),";"))))),collapse="; ")},"")
  s<-pm_load_sites(pm_path(root,sites_file),d,show_sites)
  coverage<-data.frame(week_start=weeks,week_end=weeks+6,counties=length(ids),reported=integer(length(weeks)),missing=integer(length(weeks)))
  matrices<-list()
  for(n in c("positivity","cases","colour_class","status"))matrices[[n]]<-lapply(weeks,function(w)I(unname(grid[[n]][grid$week_start==w])))
  for(i in seq_along(weeks)){coverage$reported[i]<-sum(is.finite(matrices$positivity[[i]]));coverage$missing[i]<-length(ids)-coverage$reported[i]}
  pm_csv(grid,file.path(output,"map_county_weekly.csv"));pm_csv(coverage,file.path(output,"weekly_coverage.csv"));pm_csv(s,file.path(output,"map_sites.csv"))
  manifest<-data.frame(role="background_input",file=source,md5=unname(tools::md5sum(source)),stringsAsFactors=FALSE)
  if(file.exists(pm_path(root,sites_file)))manifest<-rbind(manifest,data.frame(role="site_coordinates",file=normalizePath(pm_path(root,sites_file),winslash="/"),md5=unname(tools::md5sum(pm_path(root,sites_file)))))
  pm_csv(manifest,file.path(output,"input_manifest.csv"))
  pm_csv(data.frame(parameter=c("version","input_kind","input_rows","duplicate_site_rows_removed","first_week","last_week_end","seconds_per_week","county_boundary_source","county_boundary_zip_md5"),value=c("1.1.0",norm$input_kind,norm$input_rows,norm$duplicate_rows_removed,as.character(min(weeks)),as.character(max(weeks)+6),delay,"https://www2.census.gov/geo/tiger/GENZ2020/shp/cb_2020_us_county_20m.zip",pm_asset("county_zip_md5"))),file.path(output,"run_parameters.csv"))
  payload<-list(weeks=I(as.character(weeks)),ends=I(as.character(weeks+6)),areas=areas,sites=s,values=matrices,
    colours=pm_colours(),labels=pm_labels(),delay=delay,background_input=basename(source),input_kind=norm$input_kind)
  text<-pm_asset("template")
  replace<-function(token,value){pos<-regexpr(token,text,fixed=TRUE);if(pos<0)stop("Template token missing: ",token);text<<-paste0(substr(text,1,pos-1),value,substring(text,pos+nchar(token),nchar(text)))}
  replace("__LEAFLET_CSS__",pm_asset("leaflet_css"));replace("__LEAFLET_JS__",pm_asset("leaflet_js"));replace("__PAYLOAD__",pm_json(payload))
  replace("__COUNTIES__",pm_asset("counties"));replace("__STATES__",pm_asset("states"))
  html<-file.path(output,"county_pandemic_map.html");writeLines(enc2utf8(text),html,useBytes=TRUE)
  message("HTML: ",html)
  if(write_gif){
    enc<-pm_gif_engine(gif_engine,install_missing);message("GIF encoder: ",enc$type)
    fd<-file.path(output,"frames");dir.create(fd,showWarnings=FALSE)
    frames<-file.path(fd,paste0("week_",format(weeks,"%Y-%m-%d"),".png"))
    cs<-pm_shapes(counties);ss<-pm_shapes(states)
    for(i in seq_along(weeks)){
      message("[Frame ",i,"/",length(weeks),"] ",weeks[i])
      pm_frame(frames[i],i,weeks,grid,cs,ss,s,width,height)
      if(!file.exists(frames[i])||is.na(file.info(frames[i])$size)||file.info(frames[i])$size<100)
        stop("PNG rendering failed for ",weeks[i],"; GIF was not encoded. Rerun with a working PNG graphics device.")
    }
    pm_write_gif(frames,file.path(output,"county_pandemic_map.gif"),enc,width,height,delay)
    if(!keep_frames)unlink(frames)
  }
  writeLines(c("Weekly county COVID-19 positivity map",paste("Input:",source),
    "HTML: offline Leaflet map with play/pause, previous/next week, slider, speed, county selection and site markers.",
    "GIF: same values and fixed bins, one frame per complete Monday-Sunday week; loops continuously.",
    "GIF bottom-right timeline: first-to-last-frame progress, start/end dates and weekly counter.",
    "Grey: exactly 0% reported positivity. Red bins: >0-<5, 5-<10, 10-<15, 15-<20, 20-<30, 30-100%.",
    "White dashed counties: missing weekly value. Pale background: outside the supplied county series.",
    "Zero positivity is not proof of no infection; no interpolation or state substitution is performed.",
    "Repeated county-weeks from shared sites are collapsed only when their values agree. No percentages are averaged.",
    "The county is the site address location, not necessarily participants' residence or recruitment catchment.",
    "Cases in tooltips are weekly net reported case changes; negative corrections are retained.",
    "Boundaries: US Census 2020 cartographic counties/states 1:20,000,000, rounded to 4 decimals; contiguous US + DC.",
    "County shapes are generalized; narrow coastline or border differences do not revise the input site-to-county assignment.",
    "Leaflet 1.9.4: BSD-2-Clause; license retained in HTML. Census geography: US government public data.",
    "The clinical_trial_sites.csv and screening_map_template.html from the demographic workflow are not modified.",
    "The static original screening template is not required; this script supplies its own offline animation shell."),file.path(output,"README.txt"))
  capture.output(sessionInfo(),file=file.path(output,"sessionInfo.txt"))
  writeLines(if(write_gif)"COMPLETE: HTML and GIF" else "COMPLETE: HTML only (GIF disabled)",file.path(output,"RUN_STATUS.txt"));complete<-TRUE
  message("Done: ",length(ids)," counties; ",length(weeks)," weeks; ",nrow(s)," site markers.")
  if(open_html)utils::browseURL(html)
  invisible(list(html=html,gif=if(write_gif)file.path(output,"county_pandemic_map.gif")else NULL,data=grid,coverage=coverage))
}

